// native_stt_register.cpp — registers every native of native_stt_decl.h with
// bronze (embed::registerNative) under __bro_native.stt. Generated by brosurface
// (gen/emit_natives.mjs); do not edit. Call registerNatives_stt from registerBroNatives
// (src/bronze_host/host_natives.h) on the thread that runs the program.
//
// Class members are Function-kind natives taking the handle first (the wrapper's
// receiver is dynamic, so a Method-kind registration would be unreachable from it);
// each class has one Constructor-kind registration, which mints the class, and its
// prototype is published as __bro_native.stt.<Class>Proto for stt.js to chain.

#include "native_stt_decl.h"

#include "embed/embed.h"

#include <initializer_list>
#include <string>

namespace bro::bronze_host {

namespace {

namespace ev = bronze::embed;

ev::NativeSignature sig(const char* ret, std::initializer_list<const char*> params, ev::NativeKind kind) {
    ev::NativeSignature s;
    s.returnType = ret;
    for (const char* p : params) s.paramTypes.emplace_back(p);
    s.kind = kind;
    return s;
}

bool fn(const char* path, void* f, const char* ret, std::initializer_list<const char*> params, std::string* error) {
    return ev::registerNative(path, f, sig(ret, params, ev::NativeKind::Function), error);
}

bool ctor(const char* path, void* f, ev::HandleDestructor dtor, bronze::runtime::Finalize finalize,
          std::initializer_list<const char*> params, std::string* error) {
    ev::NativeSignature s = sig(path, params, ev::NativeKind::Constructor);
    s.className = path;
    s.destructor = dtor;
    s.finalize = finalize;
    return ev::registerNative(path, f, s, error);
}

// The prototype every instance of a class is born on, published where the
// wrapper reads it. Skipped when the roots are not there (bro-native-manifest
// registers without them; the manifest does not need the prototype).
void publishPrototype(const char* ns, const char* className, const char* protoName) {
    ev::GlobalValue root = ev::globalValue("__bro_native");
    if (!root.found || !ev::isObject(root.value)) return;
    ev::GlobalValue proto = ev::nativeClassPrototype(className);
    if (!proto.found) return;
    // Each value rooted before the next allocating call (bronze embed GC contract).
    ev::Persistent rootSlot(root.value);
    ev::Persistent protoSlot(proto.value);
    ev::Persistent nsSlot(ev::getProperty(rootSlot.get(), ns));
    if (!ev::isObject(nsSlot.get())) return;
    ev::setProperty(nsSlot.get(), protoName, protoSlot.get());
}

template <typename F>
void* p(F* f) { return reinterpret_cast<void*>(f); }

}  // namespace

bool registerNatives_stt(std::string* error) {
    bool ok =
        ctor("__bro_native.stt.WhisperTokenizer", p(&bro_stt_WhisperTokenizer_ctor), &bro_stt_WhisperTokenizer_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.stt.WhisperModel", p(&bro_stt_WhisperModel_ctor), &bro_stt_WhisperModel_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.stt.WhisperSession", p(&bro_stt_WhisperSession_ctor), &bro_stt_WhisperSession_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.stt.ParakeetTokenizer", p(&bro_stt_ParakeetTokenizer_ctor), &bro_stt_ParakeetTokenizer_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.stt.ParakeetModel", p(&bro_stt_ParakeetModel_ctor), &bro_stt_ParakeetModel_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.stt.ParakeetSession", p(&bro_stt_ParakeetSession_ctor), &bro_stt_ParakeetSession_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.stt.QwenAsrModel", p(&bro_stt_QwenAsrModel_ctor), &bro_stt_QwenAsrModel_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.stt.QwenAsrSession", p(&bro_stt_QwenAsrSession_ctor), &bro_stt_QwenAsrSession_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        ctor("__bro_native.stt.QwenAsrStream", p(&bro_stt_QwenAsrStream_ctor), &bro_stt_QwenAsrStream_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        fn("__bro_native.stt.WhisperTokenizer_loaded_get", p(&bro_stt_WhisperTokenizer_loaded_get), "bool", {"__bro_native.stt.WhisperTokenizer"}, error) &&
        fn("__bro_native.stt.WhisperModel_loaded_get", p(&bro_stt_WhisperModel_loaded_get), "bool", {"__bro_native.stt.WhisperModel"}, error) &&
        fn("__bro_native.stt.WhisperModel_device_get", p(&bro_stt_WhisperModel_device_get), "str", {"__bro_native.stt.WhisperModel"}, error) &&
        fn("__bro_native.stt.WhisperModel_createSession", p(&bro_stt_WhisperModel_createSession), "__bro_native.stt.WhisperSession", {"__bro_native.stt.WhisperModel"}, error) &&
        fn("__bro_native.stt.WhisperSession_loaded_get", p(&bro_stt_WhisperSession_loaded_get), "bool", {"__bro_native.stt.WhisperSession"}, error) &&
        fn("__bro_native.stt.WhisperSession_reset", p(&bro_stt_WhisperSession_reset), "void", {"__bro_native.stt.WhisperSession"}, error) &&
        fn("__bro_native.stt.ParakeetTokenizer_loaded_get", p(&bro_stt_ParakeetTokenizer_loaded_get), "bool", {"__bro_native.stt.ParakeetTokenizer"}, error) &&
        fn("__bro_native.stt.ParakeetModel_loaded_get", p(&bro_stt_ParakeetModel_loaded_get), "bool", {"__bro_native.stt.ParakeetModel"}, error) &&
        fn("__bro_native.stt.ParakeetModel_device_get", p(&bro_stt_ParakeetModel_device_get), "str", {"__bro_native.stt.ParakeetModel"}, error) &&
        fn("__bro_native.stt.ParakeetModel_createSession", p(&bro_stt_ParakeetModel_createSession), "__bro_native.stt.ParakeetSession", {"__bro_native.stt.ParakeetModel"}, error) &&
        fn("__bro_native.stt.ParakeetSession_loaded_get", p(&bro_stt_ParakeetSession_loaded_get), "bool", {"__bro_native.stt.ParakeetSession"}, error) &&
        fn("__bro_native.stt.ParakeetSession_reset", p(&bro_stt_ParakeetSession_reset), "void", {"__bro_native.stt.ParakeetSession"}, error) &&
        fn("__bro_native.stt.QwenAsrModel_loaded_get", p(&bro_stt_QwenAsrModel_loaded_get), "bool", {"__bro_native.stt.QwenAsrModel"}, error) &&
        fn("__bro_native.stt.QwenAsrModel_device_get", p(&bro_stt_QwenAsrModel_device_get), "str", {"__bro_native.stt.QwenAsrModel"}, error) &&
        fn("__bro_native.stt.QwenAsrModel_createSession", p(&bro_stt_QwenAsrModel_createSession), "__bro_native.stt.QwenAsrSession", {"__bro_native.stt.QwenAsrModel"}, error) &&
        fn("__bro_native.stt.QwenAsrSession_loaded_get", p(&bro_stt_QwenAsrSession_loaded_get), "bool", {"__bro_native.stt.QwenAsrSession"}, error) &&
        fn("__bro_native.stt.QwenAsrSession_reset", p(&bro_stt_QwenAsrSession_reset), "void", {"__bro_native.stt.QwenAsrSession"}, error) &&
        fn("__bro_native.stt.QwenAsrStream_loaded_get", p(&bro_stt_QwenAsrStream_loaded_get), "bool", {"__bro_native.stt.QwenAsrStream"}, error);
#if BRO_WITH_SOUNDML
    ok = ok &&
        fn("__bro_native.stt.init", p(&bro_stt_init), "void", {}, error);
#endif
    if (!ok) return false;
    publishPrototype("stt", "__bro_native.stt.WhisperTokenizer", "WhisperTokenizerProto");
    publishPrototype("stt", "__bro_native.stt.WhisperModel", "WhisperModelProto");
    publishPrototype("stt", "__bro_native.stt.WhisperSession", "WhisperSessionProto");
    publishPrototype("stt", "__bro_native.stt.ParakeetTokenizer", "ParakeetTokenizerProto");
    publishPrototype("stt", "__bro_native.stt.ParakeetModel", "ParakeetModelProto");
    publishPrototype("stt", "__bro_native.stt.ParakeetSession", "ParakeetSessionProto");
    publishPrototype("stt", "__bro_native.stt.QwenAsrModel", "QwenAsrModelProto");
    publishPrototype("stt", "__bro_native.stt.QwenAsrSession", "QwenAsrSessionProto");
    publishPrototype("stt", "__bro_native.stt.QwenAsrStream", "QwenAsrStreamProto");
    return true;
}

}  // namespace bro::bronze_host
